from dataclasses import dataclass, field
from typing import List

@dataclass
class Address:
    city: str
    zip_code: str

@dataclass
class Customer:
    name: str
    address: Address

@dataclass
class Item:
    product: str
    qty: int

@dataclass
class Order:
    customer: Customer
    items: List[Item] = field(default_factory=list)

data = [
    Order(
        customer=Customer(
            name='Ana',
            address=Address(city='Fortaleza', zip_code='60000-000')
        ),
        items=[Item('pen', 2), Item('notebook', 1)]
    )
]

def first_order_city(data):
    return data[0].customer.address.city
